// [WP Update] prepare Admin API GET /flows
// phase: "check" (v4.12.6: flow + tab in one click), "apply", "flowdl", "selfupdate" or "selfcheck" (set via msg.topic by the buttons)
// Credentials: dashboard fields first, otherwise environment variables
// WPU_ADMIN_USER / WPU_ADMIN_PASS. That is the safe route: no password
// in the editor or in the Node-RED context (only in the container environment).
// out1: GET /flows directly | out2: POST /auth/token first
const c = flow.get("WPU_cfg") || {};
const base = adminBase();
const phase = (msg.topic === "apply") ? "apply" : (msg.topic === "flowdl" ? "flowdl" : (msg.topic === "selfupdate" ? "selfupdate" : (msg.topic === "selfcheck" ? "selfcheck" : "check")));
const uiUser = (c.user !== undefined && c.user !== null) ? String(c.user).trim() : "";
// password from the session-only memory store (never on disk)
const uiPassRaw = flow.get("WPU_pass", "memory");
const uiPass = (uiPassRaw !== undefined && uiPassRaw !== null) ? String(uiPassRaw) : "";
const user = uiUser || (env.get("WPU_ADMIN_USER") || "");
const pass = uiPass || (env.get("WPU_ADMIN_PASS") || "");

function authHeader(tok) {
    const h = { "Node-RED-API-Version": "v2" };
    if (tok) { h["Authorization"] = "Bearer " + tok; }
    return h;
}
function getFlowsMsg(tok) {
    return {
        _phase: phase, _base: base,
        url: base + "/flows", method: "GET",
        headers: authHeader(tok), payload: ""
    };
}

// Continue right away without credentials or with a fresh token (max 1 hour: admin tokens
// expire server-side; refreshing proactively prevents a 401 mid-chain)
if (!user) { return [getFlowsMsg(null), null]; }
// admin token (bearer with admin rights) only in the memory store
let token = flow.get("WPU_token", "memory");
const tokenTime = flow.get("WPU_tokenTime", "memory");
if (token) {
    if (tokenTime && (Date.now() - tokenTime > 60 * 60 * 1000)) {
        flow.set("WPU_token", null, "memory");
        flow.set("WPU_tokenTime", null, "memory");
        token = null;
    } else {
        return [getFlowsMsg(token), null];
    }
}

// Fetch a token first
const tokenMsg = {
    _phase: phase, _base: base,
    url: base + "/auth/token", method: "POST",
    headers: { "Content-Type": "application/json" },
    payload: {
        client_id: "node-red-admin",
        grant_type: "password",
        scope: "*",
        username: user,
        password: pass
    }
};
return [null, tokenMsg];

function adminBase() {
    // Server-side only: loopback (this flow runs inside Node-RED) or the
    // WPU_ADMIN_BASE environment variable. NEVER from a dashboard field: that
    // would allow WPU_ADMIN_USER/PASS to be sent to an arbitrary URL
    // by someone with dashboard access only.
    const b = (env.get("WPU_ADMIN_BASE") || "").trim();
    if (b) { return b.replace(/\/+$/, ""); }
    let root = "";
    try { root = (RED.settings && RED.settings.httpAdminRoot) || ""; } catch (e) { root = ""; }
    return ("http://127.0.0.1:1880" + root).replace(/\/+$/, "");
}

// [WP Update] process the POST /auth/token response, then continue to GET /flows
const p = msg.payload || {};
if (msg.statusCode === 200 && p.access_token) {
    // token only in the memory store: never in the persistent context on disk
    flow.set("WPU_token", p.access_token, "memory");
    flow.set("WPU_tokenTime", Date.now(), "memory");
    const out = {
        _phase: msg._phase, _base: msg._base,
        url: msg._base + "/flows", method: "GET",
        headers: { "Node-RED-API-Version": "v2", "Authorization": "Bearer " + p.access_token },
        payload: ""
    };
    return [out, null];
}
// token request failed: do not stop silently, return a clear error
return [null, { payload: "Admin login failed (status " + msg.statusCode + "); Check the user/password fields. Note: with adminAuth without credentials-type Node-RED works with API keys; in that case it is best to run without login on the LAN.", topic: "WP Update error" }];

// [WP Update] process the GET /flows result
// out1 (check): show current version, then fetch version.json for the flow AND this tab (v4.12.6 merged check)
// out2 (apply): download the new flow.json
// out3 (error): error message
const st = flow.get("WPU") || {};
const raw = msg.payload;
const isV2 = !Array.isArray(raw) && raw && Array.isArray(raw.flows);
const flows = isV2 ? raw.flows : (Array.isArray(raw) ? raw : null);
if (msg.statusCode === 401) {
    flow.set("WPU_token", null, "memory");
    flow.set("WPU_tokenTime", null, "memory");
    return [null, null, { payload: "Admin login refused (401): token expired or credentials changed. Press the button again; a new token is then fetched automatically.", topic: "WP Update error" }];
}
if (!flows) {
    return [null, null, { payload: "Cannot fetch own flows via the Admin API (status " + msg.statusCode + "); Check WPU_ADMIN_BASE (environment): example http://127.0.0.1:1880", topic: "WP Update error" }];
}
const rev = isV2 ? raw.rev : null;
st.rev = rev;
st.apiV2 = isV2;

// Current version from the changelog node ("Line - Changelog": "Version 26.5.1 Stable")
let cur = null;
for (let i = 0; i < flows.length; i++) {
    const n = flows[i];
    if (n && n.name === "Line - Changelog" && typeof n.format === "string") {
        const m = /Version (\d+\.\d+\.\d+)/.exec(n.format);
        if (m) { cur = m[1]; break; }
    }
}
// fallback: any node with "changelog" in its name (a renamed node does not
// break version detection)
if (!cur) {
    for (let i = 0; i < flows.length; i++) {
        const n = flows[i];
        if (!n || !/changelog/i.test(String(n.name || ""))) { continue; }
        const fields = ["format", "info", "label"];
        for (let j = 0; j < fields.length; j++) {
            const v = n[fields[j]];
            if (typeof v === "string") {
                const m = /Version (\d+\.\d+\.\d+)/.exec(v);
                if (m) { cur = m[1]; break; }
            }
        }
        if (cur) { break; }
    }
}
st.currentVersion = cur;
flow.set("WPU", st);
// large blob only in the memory store (prevents MB-scale disk writes)
flow.set("WPU_localFlows", flows, "memory");
node.status({ text: "Current version: " + (cur || "unknown") });

const curText = cur || "unknown";
msg._phase = msg._phase || "check";
if (msg._phase === "flowdl") {
    // just the fetched flows; no version.json/download needed
    return [null, null, null, { _phase: "flowdl", _base: msg._base }];
}
if (msg._phase === "selfupdate" || msg._phase === "selfcheck") {
    // self-update: the updater repo's own version.json (pinned URL)
    return [null, null, null, null, { _phase: msg._phase, _base: msg._base, url: "https://raw.githubusercontent.com/MikeyMan83/HeishamonNR-update-tab/main/version.json?cb=" + Date.now(), method: "GET", headers: {}, payload: "" }]; // ?cb=N bypasses stale CDN edges
}
if (msg._phase === "apply") {
    if (!st.latest || !st.latest.flowUrl) {
        return [null, null, { payload: "Press [Check for updates] first: the tab must know where to fetch the new version from.", topic: "WP Update error" }];
    }
    if (st.latest.checkedAt && (Date.now() - st.latest.checkedAt > 60 * 60 * 1000)) {
        return [null, null, { payload: "Update stopped: the last version check is older than one hour, version " + st.latest.version + " may be outdated. Press [Check for updates] first, then [Update flow] again.", topic: "WP Update error" }];
    }
    const out = {
        _phase: "apply", _base: msg._base,
        url: st.latest.flowUrl + (String(st.latest.flowUrl).indexOf("?") >= 0 ? "&" : "?") + "cb=" + Date.now(), method: "GET", // v4.4.1: already normalized at storage time; encodeUri here produced %2520 = a live 404
        headers: {}, payload: ""
    };
    return [null, out, null];
}
// check branch: fetch version info for the flow AND this tab (one click, one GET /flows)
const out = {
    _phase: "check", _base: msg._base, _cur: curText,
    url: "https://raw.githubusercontent.com/edterbak/HeishaMoNR/main/version.json?cb=" + Date.now(),
    method: "GET", headers: {}, payload: ""
};
// v4.12.6: the merged [Check for updates] button also refreshes the Tab status field
const self = {
    _phase: "selfcheck", _base: msg._base,
    url: "https://raw.githubusercontent.com/MikeyMan83/HeishamonNR-update-tab/main/version.json?cb=" + Date.now(),
    method: "GET", headers: {}, payload: ""
};
return [out, null, null, null, self];

// [WP Update] compare versions (after version.json is fetched)
// out1: "Installed" field | out2: "Available" field | out3: toast/status
// out4: if version.json is missing -> repo scan (fallback)
const st = flow.get("WPU") || {};
const cur = msg._cur || st.currentVersion || "unknown";
const v = msg.payload;
if (msg.statusCode !== 200 || !v || !v.version) {
    // version.json not offered by the repo yet: scan the regular repo page
    return [ { payload: cur }, { payload: "-" }, null,
        { url: "https://github.com/edterbak/HeishaMoNR", method: "GET",
          headers: { "User-Agent": "HeishaMoNR-WP-Update-tab" }, payload: "" } ];
}
if (!/^\d+\.\d+\.\d+$/.test(String(v.version))) {
    return [ { payload: cur }, { payload: "-" },
        { payload: "version.json contains an unexpected version format (\"" + v.version + "\"); only X.Y.Z (stable) is supported.", topic: "WP Update error" },
        null ];
}
const fq = normUrl(v.flowUrl);
if (!/^https:\/\/raw\.githubusercontent\.com\/edterbak\/HeishaMoNR\//.test(fq)) {
    return [ { payload: cur }, { payload: "-" },
        { payload: "version.json contains a flowUrl outside the HeishaMoNR repo (" + v.flowUrl + "); download refused.", topic: "WP Update error" },
        null ];
}
st.latest = { version: v.version, flowUrl: fq, notes: v.notes || "", checkedAt: Date.now() };
flow.set("WPU", st);
const curKnown = !!(cur && cur !== "unknown");
if (!curKnown) {
    return [ { payload: cur }, { payload: v.version },
        { payload: "Current version unknown (no changelog node found); available: " + v.version + ". [Update flow] still works (with the 1-hour check), but check manually whether the update is really needed." + (v.notes ? " Notes: " + v.notes : ""), topic: "WP Update" },
        null ];
}
if (isNewerVersion(cur, v.version)) {
    return [ { payload: cur }, { payload: v.version + " (update!)" },
        { payload: "Update available: " + v.version + ". Make a [Back up settings] first, then press [Update flow]." + (v.notes ? " Notes: " + v.notes : ""), topic: "WP Update" },
        null ];
}
return [ { payload: cur }, { payload: v.version },
    { payload: "Up to date (" + cur + ").", topic: "WP Update" },
    null ];

function normUrl(u) {
    // v4.4.1: spaces -> %20, existing percent-encoding (done by the repo scan) is preserved
    return String(u).replace(/%(?![0-9A-Fa-f]{2})/g, "%25").replace(/ /g, "%20");
}
function isNewerVersion(a, b) {
    // NB: "unknown" is NOT "older": otherwise every check would report a phantom update
    if (!a || a === "unknown") { return false; }
    const pa = String(a).split(".").map(Number);
    const pb = String(b).split(".").map(Number);
    for (let i = 0; i < 3; i++) {
        const x = pa[i] || 0, y = pb[i] || 0;
        if (y > x) { return true; }
        if (y < x) { return false; }
    }
    return false;
}

// [WP Update] new flow.json received; now fetch palette info (GET /nodes)
const st = flow.get("WPU") || {};
if (!Array.isArray(msg.payload)) {
    return [null, { payload: "Download of the new flow.json failed (status " + msg.statusCode + ") via " + msg.url + ". Is the repo correct (flows (X.Y.Z stable).json in the root) or the flowUrl in version.json?", topic: "WP Update error" }];
}
flow.set("WPU_newFlows", msg.payload, "memory");
// integrity: the changelog node in the file must report the expected version
let newVers = null;
for (const n of msg.payload) {
    if (n && n.name === "Line - Changelog" && typeof n.format === "string") {
        const m = /Version (\d+\.\d+\.\d+)/.exec(n.format);
        if (m) { newVers = m[1]; break; }
    }
}
if (newVers && st.latest && st.latest.version && newVers !== st.latest.version) {
    return [null, { payload: "Download verification failed: the downloaded flow reports version " + newVers + " while version " + st.latest.version + " was expected (changelog node). Download refused; nothing was changed.", topic: "WP Update error" }];
}
const base = adminBase();
// GET /nodes only returns JSON with Accept: application/json (editor-api v4/v5); without it you get the HTML config blob
const headers = { "Node-RED-API-Version": "v2", "Accept": "application/json" };
const tok = flow.get("WPU_token", "memory");
if (tok) { headers["Authorization"] = "Bearer " + tok; }
msg.url = base + "/nodes";
msg.method = "GET";
msg.headers = headers;
msg.payload = "";
return [msg, null];

function adminBase() {
    // Server-side only: loopback (this flow runs inside Node-RED) or the
    // WPU_ADMIN_BASE environment variable. NEVER from a dashboard field: that
    // would allow WPU_ADMIN_USER/PASS to be sent to an arbitrary URL
    // by someone with dashboard access only.
    const b = (env.get("WPU_ADMIN_BASE") || "").trim();
    if (b) { return b.replace(/\/+$/, ""); }
    let root = "";
    try { root = (RED.settings && RED.settings.httpAdminRoot) || ""; } catch (e) { root = ""; }
    return ("http://127.0.0.1:1880" + root).replace(/\/+$/, "");
}

// ============================================================================
// [WP Update] THE CORE: id-based merge of the WP package
// Works with stable node ids (verified 26.3.1 -> 26.5.1), with
// safety nets in case Ed ever releases a version with COMPLETELY new ids:
//   - flow tabs are matched on LABEL as well as id ("WP Dash", ...;
//     labels have never changed so far); a rebuilt package then cleans
//     up the old tabs after all
//   - if the new package contains an UNCONFIGURED placeholder broker
//     (host "x.x.x.x"), all mqtt references are rewritten to the locally
//     most-used broker (prevents a silent MQTT mess after a rebuild)
// Further rules (id-stable scenario):
//   1. Nodes inside package tabs: the local definition is replaced by the new one.
//   2. Package config nodes by id: same, EXCEPT mqtt-broker: the local broker
//      ALWAYS wins (your host/port is kept).
//   3. Locally configured broker references in package mqtt nodes keep
//      the reference from the local version (prevents broken 'missing config').
//   4. Everything outside the package: untouched.
//   5. Singleton configs (global-config ui_base): only the package version.
//   6. Pre-flight: palette check and duplicate-id check before the POST.
//   7. Reporting of leftover suspicious old items (not deleted
//      automatically; see _orphanUiTabs / _suspectTabs; only on an id rebuild).
// ============================================================================
const st = flow.get("WPU") || {};
// large blobs only in the memory store: no MB-scale persistent write bursts
const local = flow.get("WPU_localFlows", "memory");
const newPkg = flow.get("WPU_newFlows", "memory");
const errMsg = (t) => [null, { payload: t, topic: "WP Update error" }, null];

if (!Array.isArray(local) || !Array.isArray(newPkg)) {
    return errMsg("Internal error: local flows or new package missing. Again: [Check] and [Update flow].");
}

// ---- 1. Palette check ----
// GET /nodes: flat list of node sets with types[] (editor-api/registry), only
// JSON with Accept: application/json (set on the /nodes request). Sets with
// err or enabled=false do not count. tab/subflow/group/junction and
// subflow:<id> are flow config types and never appear in /nodes.
const BUILTIN = new Set(["tab", "subflow", "group", "junction"]);
const sets = msg.payload;
const available = new Set();
if (!Array.isArray(sets)) {
    if (msg.statusCode === 401) {
        flow.set("WPU_token", null, "memory");
        flow.set("WPU_tokenTime", null, "memory");
        return errMsg("Admin login refused (401) while fetching palette info. Press [Check for updates] and [Update flow] again; a new token will then be fetched.");
    }
    return errMsg("Cannot read palette info (GET /nodes returned no list; status " + msg.statusCode + "). Check WPU_ADMIN_BASE or report this as a bug.");
}
for (const s of sets) {
    const entries = (s && Array.isArray(s.nodes)) ? s.nodes : [s];
    for (const e of entries) {
        if (!e || e.err || e.enabled === false) { continue; }
        const types = Array.isArray(e.types) ? e.types : (e.type ? [e.type] : []);
        for (const t of types) { available.add(t); }
    }
}
const missing = [];
for (const n of newPkg) {
    if (!n.type || BUILTIN.has(n.type) || n.type.indexOf("subflow:") === 0) { continue; }
    if (!available.has(n.type) && missing.indexOf(n.type) === -1) {
        missing.push(n.type);
    }
}
if (missing.length > 0) {
    return errMsg("Cannot update: node type(s) missing in the palette: " + missing.join(", ") + ". First install the required Node-RED libraries (see repo documentation).");
}

// ---- 2. Determine the scope ----
const pkgIds = new Set(newPkg.map(n => n.id));
const pkgTabs = newPkg.filter(n => n.type === "tab" || n.type === "subflow");
const pkgTabIds = new Set(pkgTabs.map(n => n.id));
// label of a tab, name of a subflow (subflows have name, no label)
const tabLabel = (t) => String((t.type === "subflow" ? (t.name || t.label) : (t.label || t.name)) || "").trim();
const pkgTabLabels = new Set(pkgTabs.map(tabLabel).filter(Boolean));

// Local flow tabs that belong to the package by LABEL (rebuild safety net).
// Per-label policy: a label match is only cleaned up if NOT ONE local tab
// with that label matches the package on ID (a true id rebuild). With an
// id-stable release the package tab already matches on id; an extra personal
// tab that happens to have the same label is guaranteed to survive.
const doomedLocalTabs = new Set();
const labelTabs = new Map();
for (const n of local) {
    if (n.type === "tab" || n.type === "subflow") {
        const L = tabLabel(n);
        if (pkgTabLabels.has(L)) {
            if (!labelTabs.has(L)) { labelTabs.set(L, { ids: [], onId: 0 }); }
            const e = labelTabs.get(L);
            e.ids.push(n.id);
            if (pkgTabIds.has(n.id)) { e.onId++; }
        }
    }
}
for (const e of labelTabs.values()) {
    if (e.onId === 0) { for (const id of e.ids) { doomedLocalTabs.add(id); } }
}

// ---- 3. Map the brokers ----
const localBrokers = new Set();
for (const n of local) { if (n.type === "mqtt-broker") { localBrokers.add(n.id); } }
// local broker references inside the old package (id-stable scenario)
const localBrokerRef = new Map();
for (const n of local) {
    const inPkg = pkgIds.has(n.id) || (n.z && (pkgTabIds.has(n.z) || doomedLocalTabs.has(n.z))) || doomedLocalTabs.has(n.id);
    if (inPkg && n.broker) { localBrokerRef.set(n.id, n.broker); }
}
// the locally most-used broker = the "live" broker (rebuild safety net)
const usage = {};
for (const n of local) {
    if (n.broker) { usage[n.broker] = (usage[n.broker] || 0) + 1; }
}
let liveBroker = null, liveMax = -1;
for (const id of Object.keys(usage)) {
    if (usage[id] > liveMax && localBrokers.has(id)) { liveMax = usage[id]; liveBroker = id; }
}
// package broker definitions (to recognize placeholders)
const pkgBrokerDefs = new Map();
for (const n of newPkg) { if (n.type === "mqtt-broker") { pkgBrokerDefs.set(n.id, n); } }

// keep the local global-config env: the user's environment variables
// must not get lost if the package ships its own global-config
let localGlobalEnv = null;
for (const n of local) {
    if (n.type === "global-config" && Array.isArray(n.env) && n.env.length > 0) { localGlobalEnv = n.env; }
}

// ---- 4. Local nodes: drop the package part (except the local broker) ----
const result = [];
for (const n of local) {
    const inPkg = pkgIds.has(n.id) || doomedLocalTabs.has(n.id) ||
        (n.z && (pkgTabIds.has(n.z) || doomedLocalTabs.has(n.z)));
    if (!inPkg) { result.push(n); continue; }
    if (n.type === "mqtt-broker") { result.push(n); }
}

// ---- 5. Add the new package definitions ----
const pendingBrokers = [];
for (const n of newPkg) {
    if (n.type === "mqtt-broker") {
        if (localBrokers.has(n.id)) { continue; }
        pendingBrokers.push(n);
        continue;
    }
    const def = JSON.parse(JSON.stringify(n));
    if (def.broker) {
        const pkgDef = pkgBrokerDefs.get(def.broker);
        if (pkgDef && pkgDef.broker === "x.x.x.x" && liveBroker) {
            def.broker = liveBroker; // safety net: unconfigured package broker
        } else if (localBrokerRef.has(n.id) && localBrokers.has(localBrokerRef.get(n.id))) {
            def.broker = localBrokerRef.get(n.id); // keep the local reference
        }
    }
    if (def.type === "global-config" && localGlobalEnv) {
        // merge env: local entries win, new package entries are appended
        const merged = localGlobalEnv.slice();
        for (const pe of (def.env || [])) {
            if (!merged.some(le => le.name === pe.name)) { merged.push(pe); }
        }
        def.env = merged;
    }
    result.push(def);
}
for (const b of pendingBrokers) {
    const used = result.some(n => n && n.broker === b.id);
    if (used) { result.push(b); }
}

// ---- 6. Singleton config types: only the package version ----
const SINGLETONS = ["global-config", "ui_base"];
const pkgSingletons = {};
for (const n of newPkg) { if (SINGLETONS.indexOf(n.type) !== -1) { pkgSingletons[n.type] = true; } }
for (let i = result.length - 1; i >= 0; i--) {
    const n = result[i];
    if (pkgSingletons[n.type] && !pkgIds.has(n.id)) { result.splice(i, 1); }
}

// ---- 7. Sanity: no duplicate ids ----
const seen = new Set();
for (const n of result) {
    if (seen.has(n.id)) { return errMsg("Internal error: duplicate node id after merge: " + n.id + ". NOT pushed; report this as a bug."); }
    seen.add(n.id);
}

// ---- 8. Report: leftover old items ----
// ui_tab labels of the new package ("Home", "Settings", ...): too generic to
// delete automatically, so only REPORT, and only when there is a clear
// id REBUILD going on (doomedLocalTabs > 0). In an id-stable merge a
// personal tab that happens to share its name has no place in the report.
const newUiTabNames = new Set(newPkg.filter(n => n.type === "ui_tab").map(n => String(n.name || "").trim()));
// true id rebuild = label match WITHOUT id match (in id-stable merges all
// label matches coincide with id matches and this is zero)
const rebuildDetected = Array.from(doomedLocalTabs).some(id => !pkgIds.has(id));
const orphanUiTabs = [];
if (rebuildDetected) {
    for (const n of result) {
        if (n.type === "ui_tab" && !pkgIds.has(n.id) && newUiTabNames.has(String(n.name || "").trim())) {
            orphanUiTabs.push(n.name || n.id);
        }
    }
}
// local tabs with a "WP " name that no longer fit the new package
// ("WP Personal" is the official personal tab and is excluded;
// "WP Update" is this updater tab itself: never call it "suspicious")
const suspectTabs = [];
for (const n of result) {
    if (n.type === "tab" && n.label && /^WP /i.test(String(n.label)) &&
        !/^WP (Personal|Update)$/i.test(String(n.label).trim()) &&
        !pkgTabLabels.has(String(n.label).trim())) {
        suspectTabs.push(n.label);
    }
}
let report = [];
if (orphanUiTabs.length) { report.push(orphanUiTabs.length + " old dashboard tab(s) from a previous version were left behind (name matches the new package); clean up via Configuration Nodes if empty/duplicate."); }
if (suspectTabs.length) { report.push("Local tab(s) with WP name not recognized in the new package: " + suspectTabs.join(", ") + "; possibly renamed by the developer; check manually."); }

// ---- 8b. Merge statistics: what exactly changes? ----
// Compares the running flows with the new package by id. "updated" =
// same id but different content (position x/y does not count), "new" = in the
// package but not running locally yet, "removed" = sat in a package tab
// (or was a package singleton config such as global-config/ui_base) and is dropped.
