const err = (t) => [null, null, { payload: t, topic: "WP Update error" }];
if (msg.statusCode !== 200 || !v || !v.version) {
    return err("Cannot fetch version.json (status " + msg.statusCode + "). Check internet (DNS); nothing changed.");
}
if (!/^\d+\.\d+\.\d+$/.test(String(v.version))) {
    return err("version.json contains an unexpected version format (\"" + v.version + "\"); only X.Y.Z is supported.");
}
const fq = String(v.flowUrl || "").replace(/%(?![0-9A-Fa-f]{2})/g, "%25").replace(/ /g, "%20");
if (!/^https:\/\/raw\.githubusercontent\.com\/MikeyMan83\/HeishamonNR-update-tab\//.test(fq)) {
    return err("version.json contains a flowUrl outside the HeishamonNR-update-tab repo (" + v.flowUrl + "); download refused.");
}
st.selfLatest = { version: v.version, flowUrl: fq, notes: v.notes || "", checkedAt: Date.now() };
flow.set("WPU", st);
const isNew = !cur || isNewer(cur, v.version);
// v4.12.9: the node status keeps the compact arrow, the field speaks in the same
// full sentences as the Flow status field (wpu0019)
node.status({ text: "Tab: " + (cur || "unknown") + " -> " + v.version + (isNew ? " (update!)" : " (up to date)") });
if (msg._phase === "selfupdate" && isNew) {
    node.log("[WP Update] self-update available: " + (cur || "unknown") + " -> " + v.version);
    return [{ _phase: "selfupdate", url: fq + (fq.indexOf("?") >= 0 ? "&" : "?") + "cb=" + Date.now(), method: "GET", headers: {}, payload: "" }, null, null]; // ?cb=N bypasses stale CDN edges
}
const text = isNew
    ? "Tab update available: " + v.version + (cur ? "" : " (current version unknown)") + ". Press [Update tab]." + (v.notes ? " Notes: " + v.notes : "")
    : "Up to date (" + cur + ").";
return display(text);

function isNewer(a, b) {
    if (!a) { return true; }
    const pa = String(a).split(".").map(Number);
    const pb = String(b).split(".").map(Number);
    for (let i = 0; i < 3; i++) {
        const x = pa[i] || 0, y = pb[i] || 0;
        if (y > x) { return true; }
        if (y < x) { return false; }
    }
    return false;
}

// [WP Update] self-update: validate the downloaded update-tab.json BEFORE anything is merged.
// Rules: JSON array; every id must start with "wpu" (the merge may only touch its own tab);
// unique ids; must contain the tab node wpu-tab-0001; its version must match version.json.
// out1: palette pre-flight request | out2: error
const st = flow.get("WPU") || {};
const expect = st.selfLatest && st.selfLatest.version;
const p = msg.payload;
const err = (t) => [null, { payload: t, topic: "WP Update error" }];
if (!Array.isArray(p)) {
    return err("Download of update-tab.json failed (status " + msg.statusCode + ") via " + msg.url + ". Nothing changed.");
}
const ids = p.map(n => n && n.id);
if (ids.some(id => !/^wpu/.test(String(id)))) {
    return err("Self-update refused: update-tab.json contains non-wpu node ids; only this tab itself may be replaced. Nothing changed.");
}
if (new Set(ids).size !== ids.length) {
    return err("Self-update refused: duplicate node ids in update-tab.json. Nothing changed.");
}
const tab = p.find(n => n && n.id === "wpu-tab-0001" && n.type === "tab");
if (!tab) {
    return err("Self-update refused: no wpu-tab-0001 tab node in update-tab.json. Nothing changed.");
}
if (expect && String(tab.version) !== String(expect)) {
    return err("Self-update refused: downloaded tab reports version " + (tab.version || "none") + " but " + expect + " was expected. Nothing changed.");
}
flow.set("WPU_newTab", p, "memory");
node.log("[WP Update] self-update: update-tab.json validated (" + p.length + " nodes, version " + (tab.version || "?") + ")");
// palette pre-flight, same contract as the package update (GET /nodes needs Accept: application/json)
const base = adminBase();
const tok = flow.get("WPU_token", "memory");
const headers = { "Node-RED-API-Version": "v2", "Accept": "application/json" };
if (tok) { headers["Authorization"] = "Bearer " + tok; }
return [{ url: base + "/nodes", method: "GET", headers: headers, payload: "", _phase: "selfupdate" }, null];

function adminBase() {
    const b = (env.get("WPU_ADMIN_BASE") || "").trim();
    if (b) { return b.replace(/\/+$/, ""); }
    let root = "";
    try { root = (RED.settings && RED.settings.httpAdminRoot) || ""; } catch (e) { root = ""; }
    return ("http://127.0.0.1:1880" + root).replace(/\/+$/, "");
}

// ============================================================================
// [WP Update] SELF-UPDATE MERGE: replace ONLY the wpu* nodes with the new tab.
// Everything else (HeishaMoNR package, personal tabs, brokers, other configs)
// is untouched by construction. Same deploy contract as the package update:
// palette pre-flight, duplicate-id sanity, pre-update snapshot, atomic
// POST /flows with rev. Stats (new/updated/removed/unchanged) to the log,
// summary in the deploy toast via _mergeStats.
// ============================================================================
const st = flow.get("WPU") || {};
const local = flow.get("WPU_localFlows", "memory");
const newTab = flow.get("WPU_newTab", "memory");
const errMsg = (t) => [null, { payload: t, topic: "WP Update error" }, null];
if (!Array.isArray(local) || !Array.isArray(newTab)) {
    return errMsg("Internal error: local flows or the new tab missing. Press [Update tab] again.");
}

// ---- 1. Palette pre-flight (same rules as the package update) ----
const BUILTIN = new Set(["tab", "subflow", "group", "junction"]);
const sets = msg.payload;
const available = new Set();
if (!Array.isArray(sets)) {
    if (msg.statusCode === 401) {
        flow.set("WPU_token", null, "memory");
        flow.set("WPU_tokenTime", null, "memory");
        return errMsg("Admin login refused (401) while fetching palette info. Press [Update tab] again; a new token will be fetched.");
    }
    return errMsg("Cannot read palette info (GET /nodes returned no list; status " + msg.statusCode + "). Check WPU_ADMIN_BASE or report this as a bug.");
}
for (const s of sets) {
    const entries = (s && Array.isArray(s.nodes)) ? s.nodes : [s];
    for (const e of entries) {
        if (!e || e.err || e.enabled === false) { continue; }
        const types = Array.isArray(e.types) ? e.types : (e.type ? [e.type] : []);
        for (const t of types) { available.add(t); }
    }
}
const missing = [];
for (const n of newTab) {
    if (!n.type || BUILTIN.has(n.type) || n.type.indexOf("subflow:") === 0) { continue; }
    if (!available.has(n.type) && missing.indexOf(n.type) === -1) { missing.push(n.type); }
}
if (missing.length > 0) {
    return errMsg("Cannot self-update: node type(s) missing in the palette: " + missing.join(", ") + ". Install the required Node-RED libraries first (see repo documentation).");
}

// ---- 2. Merge: drop all local wpu* nodes, append the validated new tab ----
const result = local.filter(n => !/^wpu/.test(String(n.id)));
const oldWpu = local.filter(n => /^wpu/.test(String(n.id)));
for (const n of newTab) { result.push(JSON.parse(JSON.stringify(n))); }

// ---- 3. Sanity: no duplicate ids ----
const seen = new Set();
for (const n of result) {
    if (seen.has(n.id)) { return errMsg("Internal error: duplicate node id after self-merge: " + n.id + ". NOT pushed; report this as a bug."); }
    seen.add(n.id);
}

// ---- 4. Stats (same model as the package update) ----
const stripXY = (n) => { const o = Object.assign({}, n); delete o.x; delete o.y; return JSON.stringify(o); };
const localById = new Map(oldWpu.map(n => [n.id, n]));
const stNew = [], stUpd = [];
for (const n of newTab) {
    const old = localById.get(n.id);
    if (!old) { stNew.push(n); }
    else if (stripXY(old) !== stripXY(n)) { stUpd.push(n); }
}
const newIds = new Set(newTab.map(n => n.id));
const stDel = oldWpu.filter(n => !newIds.has(n.id));
const stSame = oldWpu.length - stUpd.length - stDel.length;
const shortName = (n) => String(n.name || n.label || n.type) + " (" + n.id + ")";
const statLine = (list) => "(" + list.length + "): " + (list.length ? list.slice(0, 20).map(shortName).join("; ") + (list.length > 20 ? "; and " + (list.length - 20) + " more" : "") : "none");
node.log("[WP Update] self-update NEW nodes " + statLine(stNew));
node.log("[WP Update] self-update UPDATED nodes " + statLine(stUpd));
node.log("[WP Update] self-update REMOVED nodes " + statLine(stDel));
const stats = { added: stNew.length, updated: stUpd.length, removed: stDel.length, unchanged: stSame };

// ---- 5. POST prep: identical contract as the package update ----
const c = flow.get("WPU_cfg") || {};
const base = adminBase();
const tok = flow.get("WPU_token", "memory");
const headers = { "Content-Type": "application/json", "Node-RED-Deployment-Type": "full" };
if (st.apiV2) {
    headers["Node-RED-API-Version"] = "v2";
    if (tok) { headers["Authorization"] = "Bearer " + tok; }
} else if (tok) {
    headers["Authorization"] = "Bearer " + tok;
}
const body = (st.apiV2) ? { flows: result, rev: st.rev } : result;
node.log("[WP Update] self-update: " + oldWpu.length + " -> " + newTab.length + " wpu nodes (" + result.length + " total); POST /flows (v" + (st.apiV2 ? "2" : "1") + ", rev " + (st.rev || "-") + ")");
node.status({ text: "Updating this tab: " + newTab.length + " nodes" });
// out3: current flows written as rollback snapshot BEFORE the POST (same file pattern as package update)
const bdir = (c.backupDir || "").replace(/[\/\\]+$/, "");
const bpfx = bdir ? bdir + "/" : "";
const snapStamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-");
const snapMsg = { payload: JSON.stringify(local), filename: bpfx + "wp-preupdate-flows-" + snapStamp + ".json" };
return [{
    url: base + "/flows", method: "POST", headers: headers, payload: body,
    _phase: "selfupdate",
    _mergeStats: stats,
    _newNames: stNew.map(n => String(n.name || n.label || n.type)),
    _localCount: local.length, _newCount: result.length
}, null, snapMsg];

function adminBase() {
    const b = (env.get("WPU_ADMIN_BASE") || "").trim();
    if (b) { return b.replace(/\/+$/, ""); }
    let root = "";
    try { root = (RED.settings && RED.settings.httpAdminRoot) || ""; } catch (e) { root = ""; }
    return ("http://127.0.0.1:1880" + root).replace(/\/+$/, "");
}
